create table if not exists public.availability_rules(id uuid primary key default gen_random_uuid(),weekday smallint not null check(weekday between 1 and 7),start_time time not null,end_time time not null,valid_from date,valid_until date,is_active boolean not null default true,created_at timestamptz not null default now(),check(end_time>start_time),check(valid_from is null or valid_until is null or valid_until>=valid_from));
create table if not exists public.slot_overrides(id uuid primary key default gen_random_uuid(),consultation_method_id uuid not null references public.consultation_methods(id) on delete cascade,slot_start timestamptz not null,is_open boolean not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(consultation_method_id,slot_start));
alter table public.availability_rules enable row level security;alter table public.slot_overrides enable row level security;
create or replace function public.get_available_slots(p_method_id uuid,p_days integer default 60) returns table(slot_start timestamptz,slot_end timestamptz) language sql security definer set search_path=public as $$
with dates as(select d::date local_date from generate_series((now() at time zone 'Asia/Taipei')::date,(now() at time zone 'Asia/Taipei')::date+least(greatest(p_days,1),180),interval '1 day') d),regular as(select gs slot_start,gs+interval '30 minutes' slot_end from dates d join availability_rules r on r.is_active and extract(isodow from d.local_date)=r.weekday and(r.valid_from is null or d.local_date>=r.valid_from)and(r.valid_until is null or d.local_date<=r.valid_until)cross join lateral generate_series((d.local_date+r.start_time)at time zone 'Asia/Taipei',((d.local_date+r.end_time)at time zone 'Asia/Taipei')-interval '30 minutes',interval '30 minutes')gs),forced_open as(select o.slot_start,o.slot_start+interval '30 minutes' slot_end from slot_overrides o where o.consultation_method_id=p_method_id and o.is_open and o.slot_start>now()),combined as(select * from regular union select * from forced_open)
select c.slot_start,c.slot_end from combined c where c.slot_start>now() and not exists(select 1 from slot_overrides o where o.consultation_method_id=p_method_id and o.slot_start=c.slot_start and not o.is_open)and not exists(select 1 from bookings b where b.consultation_method_id=p_method_id and b.slot_start=c.slot_start and b.status<>'cancelled')order by c.slot_start;$$;
grant execute on function public.get_available_slots(uuid,integer) to anon;
